function onIdle(me, enemy, game) {
  var mx = me.tank.position[0];
  var my = me.tank.position[1];
  var myDir = me.tank.direction;
  var map = game.map;
  var enemyTank = enemy.tank;
  var enemyBullet = enemy.bullet;
  var star = game.star;

  var DIR_V = { up: [0,-1], down: [0,1], left: [-1,0], right: [1,0] };
  var DIR_NAME = ["up","down","left","right"];
  var OPP = { up:"down", down:"up", left:"right", right:"left" };

  function inBounds(x,y){ return x>=0 && x<map.length && y>=0 && y<map[0].length; }
  function isWall(x,y){ return !inBounds(x,y) || map[x][y]==="x"; }
  function isPassable(x,y){ return inBounds(x,y) && map[x][y]!=="x"; }

  function bulletHeadingTowardMe(bullet) {
    if (!bullet) return false;
    var bx = bullet.position[0], by = bullet.position[1];
    var bDir = bullet.direction;
    var dx = DIR_V[bDir][0], dy = DIR_V[bDir][1];
    if (dy === 0) {
      if (by !== my) return false;
      return (dx > 0 && bx < mx) || (dx < 0 && bx > mx);
    }
    if (dx === 0) {
      if (bx !== mx) return false;
      return (dy > 0 && by < my) || (dy < 0 && by > my);
    }
    return false;
  }

  function bulletDist(bullet) {
    if (!bullet) return 9999;
    return Math.abs(bullet.position[0] - mx) + Math.abs(bullet.position[1] - my);
  }

  function getDodgeDirs(bDir) {
    if (bDir === "left" || bDir === "right") return ["up", "down"];
    return ["left", "right"];
  }

  function tryMove(dir) {
    var nx = mx + DIR_V[dir][0], ny = my + DIR_V[dir][1];
    if (isPassable(nx, ny)) return dir;
    return null;
  }

  function dodgeBullet(bullet) {
    var dodgeDirs = getDodgeDirs(bullet.direction);
    for (var i = 0; i < dodgeDirs.length; i++) {
      var move = tryMove(dodgeDirs[i]);
      if (move) return move;
    }
    var back = tryMove(OPP[bullet.direction]);
    if (back) return back;
    for (var i = 0; i < DIR_NAME.length; i++) {
      var move = tryMove(DIR_NAME[i]);
      if (move) return move;
    }
    return null;
  }

  function bfs(targetPos) {
    if (!targetPos) return null;
    var tx = targetPos[0], ty = targetPos[1];
    if (mx === tx && my === ty) return null;
    var q = [[mx, my, null]];
    var vis = {};
    vis[mx + "," + my] = true;
    for (var i = 0; i < q.length; i++) {
      var x = q[i][0], y = q[i][1], fm = q[i][2];
      for (var j = 0; j < DIR_NAME.length; j++) {
        var d = DIR_NAME[j];
        var nx = x + DIR_V[d][0], ny = y + DIR_V[d][1];
        if (!isPassable(nx, ny)) continue;
        var key = nx + "," + ny;
        if (vis[key]) continue;
        vis[key] = true;
        var nextFm = fm || d;
        if (nx === tx && ny === ty) return nextFm;
        q.push([nx, ny, nextFm]);
      }
    }
    return null;
  }

  function alignedWithEnemy() {
    if (!enemyTank) return false;
    var ex = enemyTank.position[0], ey = enemyTank.position[1];
    if (mx === ex) {
      var minY = Math.min(my, ey), maxY = Math.max(my, ey);
      for (var y = minY + 1; y < maxY; y++) if (isWall(mx, y)) return false;
      return true;
    }
    if (my === ey) {
      var minX = Math.min(mx, ex), maxX = Math.max(mx, ex);
      for (var x = minX + 1; x < maxX; x++) if (isWall(x, my)) return false;
      return true;
    }
    return false;
  }

  function dirTowardEnemy() {
    if (!enemyTank) return null;
    var ex = enemyTank.position[0], ey = enemyTank.position[1];
    if (mx === ex) return ey > my ? "down" : "up";
    if (my === ey) return ex > mx ? "right" : "left";
    return null;
  }

  function facing(dir) { return myDir === dir; }

  // 1. 最高优先级：躲避子弹
  if (enemyBullet && bulletHeadingTowardMe(enemyBullet)) {
    var dist = bulletDist(enemyBullet);
    if (dist <= 6) {
      var dodgeDir = dodgeBullet(enemyBullet);
      if (dodgeDir) {
        if (facing(dodgeDir)) { me.go(); return; }
        me.turn(dodgeDir); return;
      }
    }
  }

  // 2. 使用隐身技能
  if (me.skill && me.skill.remainingCooldownFrames === 0) {
    if (enemyTank && alignedWithEnemy()) { me.cloak(); return; }
    if (star) {
      var starDist = Math.abs(mx - star[0]) + Math.abs(my - star[1]);
      if (starDist <= 4) { me.cloak(); return; }
    }
  }

  // 3. 射击逻辑
  if (enemyTank && !enemy.status.shielded && !enemy.status.cloaked) {
    var shootDir = dirTowardEnemy();
    if (shootDir) {
      if (facing(shootDir)) { me.fire(); return; }
      me.turn(shootDir); return;
    }
  }

  // 4. 目标选择：优先星星，其次敌人
  var target = star || (enemyTank && enemyTank.position);

  // 5. 向目标移动
  if (target) {
    var moveDir = bfs(target);
    if (moveDir) {
      if (facing(moveDir)) { me.go(); return; }
      me.turn(moveDir); return;
    }
  }

  // 6. 巡逻逻辑
  var forward = [mx + DIR_V[myDir][0], my + DIR_V[myDir][1]];
  if (isPassable(forward[0], forward[1])) {
    me.go(); return;
  }
  for (var i = 0; i < DIR_NAME.length; i++) {
    var d = DIR_NAME[i];
    var nx = mx + DIR_V[d][0], ny = my + DIR_V[d][1];
    if (isPassable(nx, ny) && d !== OPP[myDir]) {
      me.turn(d); return;
    }
  }
  me.turn("right");
}
